def verify_isbn(isbn: str) -> str:
    if len(isbn) != 13:
        return "Invalid ISBN length. It should be 13 digits."

    def calculate_checksum(isbn: str) -> int:
        return sum((int(digit, 10) if digit < 'X' else 10) * (12 - index) for index, digit in enumerate(isbn[:-1])) % 11

    calculated_checksum = calculate_checksum(isbn)
    if calculated_checksum == int(isbn[-1], 10):
        return "Right"
    else:
        corrected isbn = isbn[:-1] + str(11 - calculated_checksum % 11)
        return corrected isbn

